def sha(data): return hashlib.sha256(data).hexdigest()

def require(condition,message):
    if not condition: raise ValueError(message)

def verify_bytes(data,pin,label):
    require(len(data)==pin['bytes'] and sha(data)==pin['sha256'],'identity mismatch: '+label)

def pinned_records(obj):
    if isinstance(obj,dict):
        if isinstance(obj.get('path'),str) and 'sha256' in obj: yield obj
        for value in obj.values(): yield from pinned_records(value)
    elif isinstance(obj,list):
        for value in obj: yield from pinned_records(value)

def validate(payload):
    require(set(payload)==set(DECLARED_INPUTS),'declared input membership mismatch')
    for name,pin in DECLARED_INPUTS.items(): verify_bytes(payload[name],pin,name)
    read=lambda name: json.loads(payload[PACK+'/'+name])
    archive=read('ARCHIVE_INDEX.json')['sources']
    original={r['original']:r for r in archive}
    require(len(original)==len(archive),'unique source paths')
    def old(path):
        row=original[path];b=payload[row['recovery']];verify_bytes(b,row,path);return b
    def old_json(path):return json.loads(old(path))
    for row in archive: old(row['original'])
    require({r['recovery'] for r in archive}=={x for x in payload if x.startswith(PACK+'/archive/')},'archive blob closure')
    manifest=read('SOURCE_MANIFEST.json');count=0
    for frozen in manifest['freezes']:
        obj=old_json(frozen['original']);rows=obj[frozen['row_key']] if frozen['row_key'] else [obj];paths=[]
        require(len(rows)==frozen['member_count'],'freeze count')
        for row in rows:
            p=Path(row['path']);p=p if p.is_absolute() else Path(frozen['base'])/p
            verify_bytes(old(str(p)),row,str(p));paths.append(str(p))
        require(paths==frozen['members'],'freeze original path map');count+=len(rows)
    for relative,h in manifest['root_acceptance_pins'].items():
        matches=[x for x in archive if x['original'].endswith('/'+relative)]
        require(len(matches)==1 and matches[0]['sha256']==h,'acceptance identity')
    for edge in manifest['acceptance_reference_edges']:
        refs=list(pinned_records(old_json(edge['acceptance'])))
        require(any(r['path']==edge['reference'] and r['sha256']==edge['sha256'] for r in refs),'actual acceptance reference')
        require(sha(old(edge['reference']))==edge['sha256'],'reference byte identity')
    mapping=read('BODY_MAP.json');note=payload[mapping['note']]
    verify_bytes(note[:mapping['wrapper']['bytes']],mapping['wrapper'],'wrapper prefix')
    require(len(mapping['bodies'])==8,'eight unchanged resource bodies')
    end=mapping['wrapper']['bytes']
    for row in mapping['bodies']:
        require(row['start_byte']>=end and row['end_byte_exclusive']>row['start_byte'],'ordered body ranges')
        b=note[row['start_byte']:row['end_byte_exclusive']]
        verify_bytes(b,row,row['label']);require(b==old(row['original']) and note.count(b)==1,'unchanged body copy')
        end=row['end_byte_exclusive']
    parents=read('PARENT_BINDING.json')
    require(parents['direct_canonical_parents']==manifest['direct_parent_pins'],'parent pin agreement')
    for row in parents['direct_canonical_parents']:
        matches=[r for r in archive if r['original'].endswith('/'+row['path'])]
        require(len(matches)==1,'unique selected canonical parent');verify_bytes(old(matches[0]['original']),row,row['path'])
        require((']('+Path(row['path']).name+')').encode() in note,'recognized mathematical-parent Markdown citation')
    require(len(parents['direct_canonical_parents'])==4,'four current canonical mathematical sources')
    require(parents['git_base'] is None,'resource integration base remains unset')
    pub=old_json(parents['preparation_publication_record']);att=old_json(parents['preparation_attachment_record'])
    require(pub['headRefOid']==parents['preparation_canonical_commit']=='d0421bc43e396592aa5c66e2858138b1fb02f808','actual preparation source commit')
    require(pub['number']==9640 and pub['state']=='OPEN' and pub['isDraft'] is False,'actual parent publication identity')
    require(pub['source_note']['sha256']=='0c6b10f903352ff152cc920499f01c624a6407ea0e02c907a2b8b30c4ef81823','actual preparation note')
    require(att['isError'] is False and any(json.loads(x['text'])=={'artifact_type':'pull_request','url':pub['url']} for x in att['content'] if x['type']=='text'),'actual attachment envelope')
    state=read('PUBLICATION_STATE.json')
    for field in ['actual_canonical_binding','actual_root_wrapper_code_approval','actual_new_publication','current_main_or_instructions_refresh','git_base']:
        require(state[field] is None,'source-only null state: '+field)
    require(state['preparation_canonical_path']==parents['preparation_canonical_path'] and state['preparation_canonical_commit']==parents['preparation_canonical_commit'],'actual preparation state identity')
    require(state['retained_audit'] is False and state['scientific_reexecutions']==0,'no audit or science replay')
    evidence=read('ACTUAL_EVIDENCE.json')
    for run in evidence['runs']:
        e=old_json(run['receipt']);base=run['base'];schema=run['schema']
        require(e['exit_code']==run['exit_code'] and not e.get('timed_out',False),'actual historical outcome')
        command=old_json(e['launch']['path']) if schema=='phase' else e
        require(isinstance(command['argv'],list) and len(command['argv'])>1 and isinstance(command['cwd'],str) and bool(command['cwd']),'original argv/cwd')
        if schema=='phase':
            for r in pinned_records(command): verify_bytes(old(r['path']),r,'actual phase launch pin')
            require(sha(old(base+'/common_source.py'))==command['common_source_at_launch']['sha256'] and sha(old(base+'/entry_source.py'))==command['entry_source_at_launch']['sha256'],'actual captured phase source')
            require(old_json(e['stdout']['path'])==pub,'publication phase output linkage')
        for r in pinned_records(e):
            data=old(r['path']);require(sha(data)==r['sha256'],'receipt-linked byte identity')
            if 'bytes' in r:require(len(data)==r['bytes'],'receipt-linked byte count')
        if schema.startswith('nested'):
            launch=old_json(base+'/LAUNCH.json');require(all(e[k]==v for k,v in launch.items()),'launch/execution match')
        if schema=='flat-review':
            launch=old_json(base+'/LAUNCH.json');require(e['argv']==launch['argv'] and e['cwd']==launch['cwd'],'flat launch identity')
            for name,key in [('executed_source.py','source_at_launch_sha256'),('launcher_at_launch.py','launcher_at_launch_sha256')]:
                require(sha(old(base+'/'+name))==launch[key],'flat launch source')
            for name,key in [('stdout.json','stdout_sha256'),('stderr.txt','stderr_sha256')]:require(sha(old(base+'/'+name))==e[key],'flat stream')
        if schema=='flat-metadata':
            launch=old_json(base+'/LAUNCH.json');require(all(e[k]==v for k,v in launch.items()),'flat metadata launch')
            for name,key in [('executed_source.py','source_sha256'),('executed_launcher.py','launcher_sha256'),('stdout','stdout_sha256'),('stderr','stderr_sha256')]:
                require(sha(old(base+'/'+name))==e[key],'flat metadata original capture')
        if schema=='root-recorder':
            require(e['child_source_at_launch']['sha256']==e['source_capture']['sha256'],'root executed source identity')
            require(e['argv'][1]==e['child_source_at_launch']['path'],'root actual command source')
            for r in pinned_records(old_json(e['stdout']['path'])):
                require(sha(old(r['path']))==r['sha256'],'root stdout output linkage')
    return dict(scope='Provenance only; no scientific verdict or canonical certification',selected_sources=len(archive),
                immediate_freezes=len(manifest['freezes']),frozen_member_rows=count,unchanged_bodies=8,
                historical_process_records=len(evidence['runs']),scientific_reexecutions=0)

def bound_blob(root,row):
    path=Path(row['path'])
    require(not path.is_absolute() and '..' not in path.parts,'Safe relative evidence path')
    data=(root/path).read_bytes();verify_bytes(data,row,'Input identity mismatch: '+str(path));return data

def execution_evidence(root,evidence,command,source_required,historical_source_review=False):
    receipt=json.loads(bound_blob(root,evidence['execution']))
    require(receipt['exit_code']==0,'Successful captured execution required')
    require(receipt['argv']==list(command),'Actual base observation command' if not source_required else 'Exact review command')
    require(receipt['cwd']==EXPECTED_REVIEW_CWD if source_required else receipt['cwd']==EXPECTED_WORKTREE,'Actual execution cwd')
    require(receipt['start_utc']<=receipt['end_utc'] if 'end_utc' in receipt else receipt['start_utc']<=receipt['finished_utc'],'Actual execution timestamps')
    for field in ['stdout','stderr','recorder']:
        data=bound_blob(root,evidence[field]);verify_bytes(data,receipt[field],'Input identity mismatch: '+field)
    require(bound_blob(root,evidence['stderr'])==b'','Empty captured stderr')
    if source_required:
        data=bound_blob(root,evidence['source'])
        verify_bytes(data,receipt['child_source_at_launch'],'Input identity mismatch: source-at-launch')
        if historical_source_review:
            require('source_capture' not in receipt and receipt['recorder']['sha256']==EXPECTED_ROOT_RECORDER_SHA,'Historical source-review receipt identity')
        else:
            verify_bytes(data,receipt['source_capture'],'Input identity mismatch: captured source')
        require(receipt['argv'][1]==receipt['child_source_at_launch']['path'],'Actual review executable')
    return json.loads(bound_blob(root,evidence['stdout'])) if command[0]!='git' else bound_blob(root,evidence['stdout']).decode().strip()

def canonical_validate(root):
    require(isinstance(EXPECTED_CANONICAL_REVIEW_SHA,str),'Canonical review is not bound')
    manifest_data=(root/PACK/'INPUT_MANIFEST.json').read_bytes()
    require(sha(manifest_data)==MANIFEST_SHA256,'Input manifest identity')
    manifest=json.loads(manifest_data);rows=manifest['inputs']
    require(len(rows)==len({r['path'] for r in rows}),'Unique input membership')
    require(set(AUDIT_INPUT_PATHS)=={r['path'] for r in rows}|{PACK+'/INPUT_MANIFEST.json'},'Declared audit input membership')
    for row in rows:bound_blob(root,row)
    load=lambda name:json.loads((root/PACK/name).read_bytes())
    actual=load('ACTUAL_BINDING.json');note=(root/NOTE).read_bytes();mapping=load('BODY_MAP.json')
    require(actual['root_read_complete'] is True and actual['canonical_parent_binding_complete'] is True,'Actual canonical review required')
    require(actual['note_sha256']==sha(note) and actual['git_base']==EXPECTED_GIT_BASE,'Actual note/base linkage')
    require(actual['new_scientific_execution'] is False and actual['retained_audit'] is False,'No scientific status promotion')
    require(load('PARENT_BINDING.json')==EXPECTED_PARENT_BINDING==actual['parent_binding'],'Exact parent binding')
    for parent in EXPECTED_PARENT_BINDING['direct_canonical_parents']:bound_blob(root,parent)
    require(actual['source_body_pins']==EXPECTED_SOURCE_BODY_PINS,'Original body-map identity')
    require(actual['raw_bodies']==mapping['bodies'],'Canonical body identity')
    require(len(mapping['bodies'])==8,'Eight canonical bodies')
    for row,old in zip(mapping['bodies'],EXPECTED_SOURCE_BODY_PINS):
        require(row['label']==old['label'] and row['sha256']==old['sha256'],'Canonical body identity')
        body=note[row['start_byte']:row['end_byte_exclusive']]
        require(len(body)==row['bytes'] and sha(body)==row['sha256'] and note.count(body)==1,'Canonical body identity')
    require(actual['source_proposal_freeze']['sha256']==EXPECTED_SOURCE_FREEZE,'Exact source proposal freeze')
    freeze=json.loads(bound_blob(root,actual['source_proposal_freeze']))
    require(freeze['scientific_executions']==0 and freeze['actual_resource_canonical_binding'] is None,'Original source-only scope')
    original_note=bound_blob(root,actual['source_draft_note'])
    original_map=bound_blob(root,actual['source_draft_body_map'])
    require(sha(original_map)==EXPECTED_SOURCE_MAP_SHA,'Exact source body-map identity')
    source_payload={name:(root/name).read_bytes() for name in DECLARED_INPUTS}
    source_payload[NOTE]=original_note;source_payload[PACK+'/BODY_MAP.json']=original_map
    # Reuse the source-approved complete source/freezes/receipts verifier unchanged.
    validate(source_payload)
    review_bytes=bound_blob(root,actual['root_review_evidence']['review'])
    require(sha(review_bytes)==EXPECTED_ROOT_REVIEW_SHA,'Exact root review identity');review=json.loads(review_bytes)
    require(review['source_freeze']['sha256']==EXPECTED_SOURCE_FREEZE and review['immutable_bodies']==8,'Actual source-review linkage')
    verify_bytes(original_note,review['source_note'],'Reviewed source note')
    require(review['scientific_reexecutions']==0 and review['actual_canonical_acceptance'] is None and review['retained_audit'] is False,'Original source-review scope')
    observed=execution_evidence(root,actual['root_review_evidence'],EXPECTED_ROOT_REVIEW_COMMAND,True,True)
    require(observed['review']['sha256']==EXPECTED_ROOT_REVIEW_SHA and observed['review']['bytes']==len(review_bytes),'Actual review output linkage')
    verify_bytes(bound_blob(root,actual['root_review_evidence']['freeze']),observed['freeze'],'Actual review freeze linkage')
    verify_bytes(bound_blob(root,actual['root_review_evidence']['review_text']),review['review'],'Actual review prose linkage')
    require(sha(bound_blob(root,actual['root_review_evidence']['execution']))==EXPECTED_ROOT_EXECUTION_SHA,'Historical source-review receipt identity')
    evidence=actual['canonical_review_evidence'];raw=bound_blob(root,evidence['review'])
    require(sha(raw)==EXPECTED_CANONICAL_REVIEW_SHA,'Exact canonical review identity');canonical=json.loads(raw)
    require(canonical['root_read_complete'] is True and canonical['bound_note_sha256']==sha(note),'Actual canonical note review')
    require(canonical['canonical_body_pins']==mapping['bodies'] and canonical['parent_binding']==EXPECTED_PARENT_BINDING,'Actual canonical body/parent review')
    require(canonical['source_draft_freeze_sha256']==EXPECTED_SOURCE_FREEZE and canonical['source_draft_review_sha256']==EXPECTED_ROOT_REVIEW_SHA,'Canonical source linkage')
    require(canonical['git_base']==EXPECTED_GIT_BASE and canonical['prebinding_primary']==EXPECTED_PREBINDING_PRIMARY and canonical['integration_common']==EXPECTED_INTEGRATION_COMMON,'Canonical implementation linkage')
    observed=execution_evidence(root,evidence,EXPECTED_CANONICAL_REVIEW_COMMAND,True)
    require(observed['review']['sha256']==EXPECTED_CANONICAL_REVIEW_SHA,'Canonical review operation linkage')
    local=json.loads(bound_blob(root,actual['base_observation']))
    require(local['observed_commit']==EXPECTED_GIT_BASE and local['source_revision_verified'] is True,'Actual local base identity')
    require(execution_evidence(root,local['execution_evidence'],('git','rev-parse','HEAD'),False)==EXPECTED_GIT_BASE,'Actual local HEAD linkage')
    command=('gh','pr','view',str(EXPECTED_BASE_PR),'--repo',EXPECTED_REPOSITORY,'--json','number,state,isDraft,headRefOid,headRefName,baseRefName,url')
    base=execution_evidence(root,actual['parent_pr_observation'],command,False)
    require(base['number']==EXPECTED_BASE_PR and base['headRefOid']==EXPECTED_GIT_BASE and base['headRefName']==EXPECTED_BASE_BRANCH and base['baseRefName']==EXPECTED_BASE_PARENT_BRANCH,'Actual base PR identity')
    require(base['state'] in ('OPEN','MERGED') and base['isDraft'] is False,'Regular actual base PR')
    paths={actual[k]['path'] for k in ['source_proposal_freeze','source_draft_body_map','source_draft_note','base_observation']}
    for group in ['root_review_evidence','canonical_review_evidence','parent_pr_observation']:
        paths.update(r['path'] for r in actual[group].values())
    paths.update(r['path'] for r in local['execution_evidence'].values())
    require(set(actual['receipt_paths'])==paths and len(actual['receipt_paths'])==len(paths),'Exact binding evidence membership')
    return {'result':'source_integrity_verified','scope':'Exact source/body/review/base/receipt provenance only',
            'scientific_programs_run_this_primary':0,'historical_programs_replayed':0,'mathematics_or_retention_certified':False}

def main():
    parser=argparse.ArgumentParser(description='Canonical resource provenance primary; no scientific execution')
    parser.add_argument('--root',type=Path,default=Path(__file__).resolve().parents[1])
    parser.add_argument('--source-only',action='store_true')
    args=parser.parse_args();root=args.root.resolve()
    if args.source_only:
        payload={name:(root/name).read_bytes() for name in DECLARED_INPUTS}
        print(json.dumps({'source_only':validate(payload),'canonical_certification':False},sort_keys=True));return 0
    report=canonical_validate(root);print(json.dumps(report,sort_keys=True))
    print('per_element: exact source coefficients retained; no physical element tested')
    print('per_site: conditional fixed incident budgets retained; no hardware slew certificate')
    print('per_mode: fixed preparation U_E and shrinking-runtime phase contracts remain distinct')
    print('per_block: full physical A2 and scalar reserves retained; provenance checks only')
    print('lattice_wide: no shrinking-family preparation, arbitrary-oracle wall time, halt/reuse or retained audit')
    return 0

if __name__ == "__main__": sys.exit(main())
